// ============================================================================
// Timer_WDT_apb: APB4 register wrapper around Timer_WDT_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/Timer_WDT.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/Timer_WDT.md
// ============================================================================
module Timer_WDT_apb #(
  parameter logic [3:0] AXI_ID = 4'd11
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic wdt_reset,
  output logic [3:0] m_awid,
  output logic [31:0] m_awaddr,
  output logic [7:0] m_awlen,
  output logic [2:0] m_awsize,
  output logic [1:0] m_awburst,
  output logic [2:0] m_awprot,
  output logic m_awvalid,
  input logic m_awready,
  output logic [31:0] m_wdata,
  output logic [3:0] m_wstrb,
  output logic m_wlast,
  output logic m_wvalid,
  input logic m_wready,
  input logic [3:0] m_bid,
  input logic [1:0] m_bresp,
  input logic m_bvalid,
  output logic m_bready,
  output logic [3:0] m_arid,
  output logic [31:0] m_araddr,
  output logic [7:0] m_arlen,
  output logic [2:0] m_arsize,
  output logic [1:0] m_arburst,
  output logic [2:0] m_arprot,
  output logic m_arvalid,
  input logic m_arready,
  input logic [3:0] m_rid,
  input logic [31:0] m_rdata,
  input logic [1:0] m_rresp,
  input logic m_rlast,
  input logic m_rvalid,
  output logic m_rready
);
  localparam logic [31:0] ID_VALUE = 32'h5C0C0100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [14:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd15) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [15:0]   c_prescale;
  logic          c_tmr_en;
  logic [31:0]   c_period;
  logic          c_ts_en;
  logic [31:0]   c_ts_base;
  logic [15:0]   c_ts_words;
  logic          c_wdt_en;
  logic [31:0]   c_wdt_load;
  logic          c_kick;
  logic [31:0]   c_count;
  logic [15:0]   c_ts_wp;
  logic [15:0]   c_ts_missed;
  logic [31:0]   c_wdt_count;
  logic          c_wdt_reset;
  logic          c_tmr_irq;
  logic          c_bark;
  logic          c_ts_err;
  Timer_WDT_top #(.AXI_ID(AXI_ID)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .prescale(c_prescale),
    .tmr_en(c_tmr_en),
    .period(c_period),
    .ts_en(c_ts_en),
    .ts_base(c_ts_base),
    .ts_words(c_ts_words),
    .wdt_en(c_wdt_en),
    .wdt_load(c_wdt_load),
    .kick(c_kick),
    .count(c_count),
    .ts_wp(c_ts_wp),
    .ts_missed(c_ts_missed),
    .wdt_count(c_wdt_count),
    .wdt_reset(c_wdt_reset),
    .tmr_irq(c_tmr_irq),
    .bark(c_bark),
    .ts_err(c_ts_err),
    .m_awid(m_awid),
    .m_awaddr(m_awaddr),
    .m_awlen(m_awlen),
    .m_awsize(m_awsize),
    .m_awburst(m_awburst),
    .m_awprot(m_awprot),
    .m_awvalid(m_awvalid),
    .m_awready(m_awready),
    .m_wdata(m_wdata),
    .m_wstrb(m_wstrb),
    .m_wlast(m_wlast),
    .m_wvalid(m_wvalid),
    .m_wready(m_wready),
    .m_bid(m_bid),
    .m_bresp(m_bresp),
    .m_bvalid(m_bvalid),
    .m_bready(m_bready),
    .m_arid(m_arid),
    .m_araddr(m_araddr),
    .m_arlen(m_arlen),
    .m_arsize(m_arsize),
    .m_arburst(m_arburst),
    .m_arprot(m_arprot),
    .m_arvalid(m_arvalid),
    .m_arready(m_arready),
    .m_rid(m_rid),
    .m_rdata(m_rdata),
    .m_rresp(m_rresp),
    .m_rlast(m_rlast),
    .m_rvalid(m_rvalid),
    .m_rready(m_rready)
  );
  assign wdt_reset = c_wdt_reset;  // also readable in the registers

  // ---------------- registers ----------------
  logic [2:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [18:0] r_CTRL;   // 12'h014 CTRL
  logic [31:0] r_PERIOD;   // 12'h018 PERIOD
  logic [31:0] r_TS_BASE;   // 12'h01C TS_BASE
  logic [15:0] r_TS_WORDS;   // 12'h020 TS_WORDS
  logic [31:0] r_WDT_LOAD;   // 12'h024 WDT_LOAD
  logic [0:0] p_CMD;   // 12'h028 CMD (pulses)

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CTRL <= 19'h0;
      r_PERIOD <= 32'h0;
      r_TS_BASE <= 32'h0;
      r_TS_WORDS <= 16'h0;
      r_WDT_LOAD <= 32'h0;
      p_CMD <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[2:0] & wmask[2:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[2:0]) | (PWDATA[2:0] & wmask[2:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CTRL <= (r_CTRL & ~wmask[18:0]) | (PWDATA[18:0] & wmask[18:0]);
      if (wr && hit[6]) r_PERIOD <= (r_PERIOD & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7]) r_TS_BASE <= (r_TS_BASE & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8]) r_TS_WORDS <= (r_TS_WORDS & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[9]) r_WDT_LOAD <= (r_WDT_LOAD & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      p_CMD <= (wr && hit[10]) ? PWDATA[0:0] & wmask[0:0] : '0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_prescale = r_CTRL[15:0];
  assign c_tmr_en = r_CTRL[16:16];
  assign c_ts_en = r_CTRL[17:17];
  assign c_wdt_en = r_CTRL[18:18];
  assign c_period = r_PERIOD[31:0];
  assign c_ts_base = r_TS_BASE[31:0];
  assign c_ts_words = r_TS_WORDS[15:0];
  assign c_wdt_load = r_WDT_LOAD[31:0];
  assign c_kick = p_CMD;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_tmr_irq;
    irq_set[1] = c_bark;
    irq_set[2] = c_ts_err;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CTRL);
      10'd6: apb_rdata = 32'(r_PERIOD);
      10'd7: apb_rdata = 32'(r_TS_BASE);
      10'd8: apb_rdata = 32'(r_TS_WORDS);
      10'd9: apb_rdata = 32'(r_WDT_LOAD);
      10'd11: apb_rdata = 32'({c_count});
      10'd12: apb_rdata = 32'({c_ts_missed, c_ts_wp});
      10'd13: apb_rdata = 32'({c_wdt_count});
      10'd14: apb_rdata = 32'({c_wdt_reset});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
